import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import { UserResponse } from '~/entities/pin/api/dtos/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { queries } from '~/shared/api/query-keys';
import { getGlobalQueryClient } from '~/shared/config/query';
import { resultify } from '~/shared/lib/utils/resultify';

const updateDefaultWallet = (aliasNm: string) => {
  return resultify(axios.post<any>(API_URLS.updateCstmrDefaultWallet(aliasNm), {}));
};

const syncDefaultWalletCache = (aliasNm: string) => {
  const queryClient = getGlobalQueryClient();
  const walletListQueryKey = queries.cstr.cstmrWalletList.queryKey;
  const userQueryKey = queries.cstr.cstmr({ cstmrNo: 'detail' }).queryKey;

  queryClient.setQueryData<UserWalletResponse[]>(walletListQueryKey, (prev = []) =>
    prev.map((wallet) => ({
      ...wallet,
      dfltAliasNm: aliasNm,
    })),
  );

  queryClient.setQueryData<UserResponse>(userQueryKey, (prev) => {
    if (!prev) {
      return prev;
    }

    const walletList = queryClient.getQueryData<UserWalletResponse[]>(walletListQueryKey) ?? [];
    const selectedWallet = walletList.find((wallet) => wallet.aliasNm === aliasNm);

    if (!selectedWallet) {
      return {
        ...prev,
        tbCstmrMastr: {
          ...prev.tbCstmrMastr,
          aliasNm,
        },
      };
    }

    return {
      ...prev,
      tbCstmrMastr: {
        ...prev.tbCstmrMastr,
        aliasNm: selectedWallet.aliasNm,
        bankCd: selectedWallet.bankCd,
        bankNm: selectedWallet.bankNm,
        walletId: selectedWallet.walletId,
        walletAliasNm: selectedWallet.walletAliasNm,
        realAcnutNo: selectedWallet.realAcnutNo,
        acnutnoBlce: selectedWallet.acnutnoBlce,
      },
    };
  });
};

export const useUpdateDefaultWalletMutation = (options?: MutationOptions<string, CBDCAxiosError, string>) => {
  const { onSuccess, ...mutationOptions } = options ?? {};

  const mutation = useMutation<string, CBDCAxiosError, string>({
    ...mutationOptions,
    mutationFn: (params: string) => updateDefaultWallet(params),
    onSuccess: async (data, variables, onMutateResult, context) => {
      await onSuccess?.(data, variables, onMutateResult, context);
      syncDefaultWalletCache(variables);
    },
  });

  return {
    ...mutation,
  };
};
